let lang='zh',data,stopAt=null;const $=s=>document.querySelector(s);const tr=(zh,en)=>lang==='zh'?zh:en;const pitchNames=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
for(let i=0;i<12;i++)$('#tonic').add(new Option(`1 = ${pitchNames[i]}4`,String(i)));
function degree(p){const r=p-60-Number($('#tonic').value);return {label:['1','♯1','2','♯2','3','4','♯4','5','♯5','6','♯6','7'][((r%12)+12)%12],octave:Math.floor(r/12)}}
function noteName(p){return pitchNames[p%12]+(Math.floor(p/12)-1)}
function el(tag,attr={},text){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attr))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-zh]').forEach(e=>e.textContent=e.dataset[lang]);$('#lang').textContent=lang==='zh'?'English':'中文';if(!data)return;document.querySelectorAll('audio').forEach(a=>a.pause());stopAt=null;$('#selection').textContent='';const r=data.records[Number($('#record').value)],key=$('#method').value,notes=r[key],s=r.stats;
$('#players').innerHTML=[['original',tr('原录音','Original recording'),`../audio/${r.id}.mp3`],['pyin',tr('pYIN 分段回放','pYIN segmented replay'),`${r.id}-pyin.wav`],['basic-pitch',tr('Basic Pitch 回放','Basic Pitch replay'),`${r.id}-basic-pitch.wav`]].map(([id,title,src])=>`<div class="player"><h3>${title}</h3><audio id="audio-${id}" controls preload="metadata" src="${src}"></audio></div>`).join('');document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>{document.querySelectorAll('audio').forEach(b=>{if(b!==a)b.pause()});if(a.id!=='audio-original')stopAt=null}));$('#audio-original').addEventListener('timeupdate',e=>{if(stopAt!==null&&e.target.currentTime>=stopAt){e.target.pause();stopAt=null}});
const lanes=[];const placed=notes.map((n,i)=>{const halfLabel=s.duration*17/1024,center=(n.start+n.end)/2;let lane=lanes.findIndex(end=>end<=Math.min(n.start,center-halfLabel));if(lane<0)lane=lanes.length;lanes[lane]=Math.max(n.end,center+halfLabel);return {...n,lane,i}});const w=1100,pad=38,h=80+Math.max(1,lanes.length)*66,x=t=>pad+t/s.duration*(w-pad*2);const svg=el('svg',{viewBox:`0 0 ${w} ${h}`,role:'img','aria-label':tr('按原始时间排列的简谱草稿','Numbered notes on original recording time')});for(let t=0;t<=s.duration;t++){svg.append(el('line',{x1:x(t),x2:x(t),y1:30,y2:h-25,stroke:'#dce3db'}));svg.append(el('text',{x:x(t),y:20,'font-size':12,'text-anchor':'middle',fill:'#64736b'},`${t}s`))}
placed.forEach(n=>{const d=degree(n.midi),y=52+n.lane*66,g=el('g',{class:'note',tabindex:0,role:'button','aria-label':`${noteName(n.midi)}, ${n.start.toFixed(2)}–${n.end.toFixed(2)} s`}),cx=(x(n.start)+x(n.end))/2;g.append(el('rect',{x:x(n.start),y,width:Math.max(2,x(n.end)-x(n.start)),height:28,rx:3,fill:key==='pyin'?'#d1e4dc':'#f1d7ce'}));g.append(el('text',{x:cx,y:y+21,'text-anchor':'middle','font-size':16,fill:'#20332e'},d.label));for(let j=0;j<Math.abs(d.octave);j++)g.append(el('circle',{cx,cy:d.octave>0?y-6-j*7:y+35+j*7,r:1.8,fill:'#20332e'}));g.append(el('title',{},`${noteName(n.midi)} · ${n.start.toFixed(2)}–${n.end.toFixed(2)} s`));const play=()=>{const a=$('#audio-original');a.currentTime=n.start;stopAt=n.end;$('#selection').textContent=`${noteName(n.midi)} · ${n.start.toFixed(2)}–${n.end.toFixed(2)} s`;a.play().catch(()=>{$('#selection').textContent=tr('无法播放，请检查浏览器声音设置。','Playback failed. Check browser sound settings.')})};g.addEventListener('click',play);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();play()}});svg.append(g)});$('#score').replaceChildren(svg);
$('#note-table').innerHTML=notes.map((n,i)=>{const d=degree(n.midi);return `<tr><td>${i+1}</td><td>${n.start.toFixed(3)}</td><td>${(n.end-n.start).toFixed(3)}</td><td>${noteName(n.midi)}</td><td>${d.label}${d.octave?` (${d.octave>0?'+':''}${d.octave} oct.)`:''}</td></tr>`}).join('');$('#downloads').innerHTML=`<a href="${r.id}-${key}.mid" download>MIDI</a><a href="${r.id}-${key}.csv" download>CSV (1=C4)</a><a href="${r.id}-${key}.wav" download>WAV</a><a href="${r.id}-basic-pitch-with-bends.mid" download>${tr('Basic Pitch 弯音 MIDI','Basic Pitch MIDI with bends')}</a>`;
$('#findings').textContent=r.id==='ecura-0118'?tr('118：两种方法的主要音区较接近，但音符数量和边界不同。pYIN 在部分连续长音附近反复跨过半音量化边界，可能产生碎片化音符。','118: Main pitch ranges are close, but note counts and boundaries differ. pYIN crosses semitone rounding boundaries within some continuous passages, potentially fragmenting sustained notes.'):tr('119：Basic Pitch 在 7.74–7.95 秒给出 E6（MIDI 88）；同期 pYIN 约为 F♯3（MIDI 54），相差约 34 个半音。这是需要回听核查的高音候选，不能当作确定的旋律或和弦。','119: Basic Pitch gives E6 (MIDI 88) at 7.74–7.95 s; pYIN is near F♯3 (MIDI 54), roughly 34 semitones apart. This high-note candidate requires review and is not an established melody note or chord.');
$('#stats').innerHTML=[[s.pyin_notes,tr('pYIN 分段音符','pYIN segmented notes')],[s.basic_pitch_notes,tr('Basic Pitch 音符','Basic Pitch notes')],[(100*s.basic_pitch_simultaneous_note_fraction).toFixed(1)+'%',tr('Basic Pitch 多音重叠时间占比','Basic Pitch overlap / full duration')],[(100*s.nearest_basic_pitch_note_within_50_cents_on_joint_frames).toFixed(1)+'%',tr('共同有效时刻相差 ≤ 半个半音','Joint estimates within 50 cents')]].map(([n,l])=>`<div class="stat"><strong>${n}</strong><span>${l}</span></div>`).join('');$('#comparison').src=`${r.id}-comparison.png`}
$('#lang').onclick=()=>{lang=lang==='zh'?'en':'zh';render()};['record','method','tonic'].forEach(id=>$('#'+id).onchange=render);render();try{const response=await fetch('results.json');if(!response.ok)throw Error(response.status);data=await response.json();render();window.__transcriptionTrial=data}catch(e){$('#selection').textContent=tr('数据加载失败，请通过本地服务器打开。','Could not load data. Open via the local server.');console.error(e)}
